#define TRANSFORM_COUNT 6
#define ITERATION_COUNT 3
mat3 transformations[TRANSFORM_COUNT];
#define PI 3.1415962


void setupITS() {
    float tao = 2.0 * PI;
    for (int i = 0; i < TRANSFORM_COUNT; i++) {
        float loopNumFloat = float(i);
        transformations[i] = mat3(sin(loopNumFloat* PI / 7.0) * 2.5,
                                  cos(loopNumFloat * PI /7.0) * 2.5,
                                  0.0, 
                                  cos( loopNumFloat * PI / 7.0) * 2.5, 
                                  sin(loopNumFloat * PI /7.0)  * 2.5,
                                  0.0, 
                                  0.125 * sin(fract(iTime/122.0) +loopNumFloat * PI/8.0), 
                                  0.125 * cos(fract(iTime/133.0) +loopNumFloat * PI/8.0), 
                                  2.0)/ 2.0;

    }

}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    setupITS();
	vec3 uv = vec3(fragCoord.xy / iResolution.xy, 1.0) - vec3(0.5);
    float divisor = float(TRANSFORM_COUNT );
    vec4 color = texture(iChannel0, uv.xy + vec2(0.5)) / divisor ; 
    for (int h = 0; h < TRANSFORM_COUNT; h++) {
        float reducer = divisor;
        for (int i = 0; i < ITERATION_COUNT; i++) {
            //reducer *= 1.25;
            vec3 location = transformations[h] * uv;
            for (int j = 0; j < TRANSFORM_COUNT; j++) {
				if (j == h) continue;
                color += texture(iChannel0,  location.xy + vec2(0.5))/reducer;
                location = transformations[i] * location;
                reducer *= 2.1;
            }

        }
    }
	fragColor = color;
}
